/* ═══════════════════════════════════════════════════════════
   PRINTMON DESIGN SYSTEM — MASTER TOKEN MAP

   Layer 1 (HUE):  3 color families define the theme identity
   Layer 2 (ALPHA): transparency variants derived from each hue
   Layer 3 (GLOW):  warm + cool box-shadow colors (RGB tuples)
   Layer 4 (SURFACE): dark/light backgrounds

   AI remaps Layer 1 hex values. Everything else flows from them.
   ═══════════════════════════════════════════════════════════ */

:root {
  --pm-hue1: #facc15;
  --pm-hue1-rgb: 250, 204, 21;
  --pm-hue1-deep: #7d660b;
  --pm-hue1-deep-rgb: 125, 102, 11;
  --pm-hue1-bright: #fcde67;
  --pm-hue1-bright-rgb: 252, 222, 103;
  --pm-hue2: #bfa53f;
  --pm-hue2-rgb: 191, 165, 63;
  --pm-hue2-bright: #cfbc6f;
  --pm-hue2-bright-rgb: 207, 188, 111;
  --pm-hue2-deep: #7c6b29;
  --pm-hue2-deep-rgb: 124, 107, 41;
  --pm-hue3: #f97316;
  --pm-hue3-rgb: 249, 115, 22;
  --pm-hue3-light: #fbab73;
  --pm-hue3-light-rgb: 251, 171, 115;
  --pm-surface: #141002;
  --pm-surface-rgb: 20, 16, 2;
  --pm-surface-alt: #110e02;
  --pm-surface-alt-rgb: 17, 14, 2;
  --pm-light: #fdedad;
  --pm-light-rgb: 253, 237, 173;
  --pm-neutral: #e3e3e3;
  --pm-neutral-rgb: 227, 227, 227;
  --pm-text: #ffffff;
  --pm-text-rgb: 255, 255, 255;
  --pm-text-dark: #000000;
  --pm-text-dark-rgb: 0, 0, 0;
  --pm-glow-warm: 191, 165, 63;
  --pm-glow-cool: 251, 157, 92;
}

/* ═══════════════════════════════════════════════════════════
   ELEMENT RULES
   All colors reference the token map above.
   Alpha variants use rgba(var(--pm-xxx-rgb), alpha).
   ═══════════════════════════════════════════════════════════ */

.printbox {
    background-color: rgba(var(--pm-surface-rgb), 0.50);
    border: 5px double rgba(var(--pm-hue2-rgb), 0.95);
}

h1 {
    color: rgba(var(--pm-hue1-rgb), 0.76);
    text-shadow: 2px 2px rgba(var(--pm-hue2-rgb), 0.84);
}

.subtitle {
    color: rgba(var(--pm-hue3-light-rgb), 0.77);
    font-family: 'Amazon Ember', 'system-ui';
}

.input-group label {
    color: var(--pm-hue3-light);
}

.input-group label span {
    color: var(--pm-hue3);
}

input[type="text"] {
    border: 1.5px solid rgba(var(--pm-hue1-rgb), 0.81);
}

/* ─── PRIMARY BUTTON ─── */

.print-button {
    background: linear-gradient(120deg,
        rgba(var(--pm-hue3-light-rgb), 0.75),
        rgba(var(--pm-hue1-rgb), 0.74));
    color: var(--pm-text);
    box-shadow:
        0 0 15px rgba(var(--pm-glow-warm), 0.5),
        0 0 30px rgba(var(--pm-glow-cool), 0.3);
}

.print-button:hover {
    background: linear-gradient(145deg,
        rgba(var(--pm-hue1-bright-rgb), 0.81),
        var(--pm-hue2-bright));
    box-shadow:
        0 0 20px rgba(var(--pm-glow-warm), 0.7),
        0 0 40px rgba(var(--pm-glow-cool), 0.5);
}

/* ─── QUICK-PRINT BUTTONS ─── */

.buttonsLine1 {
    background: linear-gradient(145deg,
        rgba(var(--pm-hue1-bright-rgb), 0.81),
        var(--pm-hue2-bright));
    color: var(--pm-text);
    box-shadow:
        0 0 15px rgba(var(--pm-glow-warm), 0.7),
        0 0 30px rgba(var(--pm-glow-cool), 0.5);
}
.buttonsLine1:hover {
    background: linear-gradient(145deg,
        rgba(var(--pm-hue3-light-rgb), 0.75),
        rgba(var(--pm-hue1-rgb), 0.74));
    box-shadow:
        0 0 20px rgba(var(--pm-glow-warm), 0.9),
        0 0 40px rgba(var(--pm-glow-cool), 0.7);
}

.buttonsLine2 {
    background: linear-gradient(195deg,
        rgba(var(--pm-hue1-bright-rgb), 0.81),
        var(--pm-hue2-bright));
    color: var(--pm-text);
    box-shadow:
        0 0 15px rgba(var(--pm-glow-warm), 0.7),
        0 0 30px rgba(var(--pm-glow-cool), 0.5);
}
.buttonsLine2:hover {
    background: linear-gradient(145deg,
        rgba(var(--pm-hue3-light-rgb), 0.75),
        rgba(var(--pm-hue1-rgb), 0.74));
    box-shadow:
        0 0 20px rgba(var(--pm-glow-warm), 0.9),
        0 0 40px rgba(var(--pm-glow-cool), 0.7);
}

.buttonsLine3 {
    background: linear-gradient(70deg,
        rgba(var(--pm-hue1-bright-rgb), 0.81),
        var(--pm-hue2-bright));
    color: var(--pm-text);
    box-shadow:
        0 0 15px rgba(var(--pm-glow-warm), 0.7),
        0 0 30px rgba(var(--pm-glow-cool), 0.5);
}
.buttonsLine3:hover {
    background: linear-gradient(145deg,
        rgba(var(--pm-hue3-light-rgb), 0.75),
        rgba(var(--pm-hue1-rgb), 0.74));
    box-shadow:
        0 0 20px rgba(var(--pm-glow-warm), 0.9),
        0 0 40px rgba(var(--pm-glow-cool), 0.7);
}

/* ─── BUTTON STATE OVERRIDES ─── */

.quick-print-buttons button:hover {
    background-color: rgba(var(--pm-hue1-bright-rgb), 0.52);
    border-color: var(--pm-hue1-bright);
}
.quick-print-buttons button:active {
    background-color: rgba(var(--pm-hue3-rgb), 0.49);
    border-color: var(--pm-hue3);
}

/* ─── SCROLLBAR ─── */

.scroll-container {
    scrollbar-color:
        rgba(var(--pm-hue1-bright-rgb), 0.81)
        rgba(var(--pm-hue1-deep-rgb), 0.68);
}

.scroll-button {
    background-color: rgba(var(--pm-hue2-bright-rgb), 0.84);
}
.scroll-button:hover {
    background-color: var(--pm-hue2-deep);
}

/* ─── ASIN STICKER ─── */

.asin-sticker-container {
    background-color: rgba(var(--pm-surface-alt-rgb), 0.64);
    border: 2px dashed rgba(var(--pm-text-rgb, 255, 255, 255), 0.80);
}
.asin-sticker-header {
    color: var(--pm-text);
}
.asin-sticker-content button {
    background-color: rgba(var(--pm-hue2-deep-rgb), 0.91);
}
.asin-sticker-content button:hover {
    background-color: rgba(var(--pm-hue3-light-rgb), 0.75);
}

/* ─── MULTI-BARCODE PRINTER ─── */

.MultiBarcode-printer {
    background-color: rgba(var(--pm-surface-rgb), 0.59);
    border: 5px double rgba(var(--pm-hue2-rgb), 0.95);
}
.MultiBarcode-printer h2 {
    color: var(--pm-text);
    text-shadow: 2px 2px rgba(var(--pm-hue1-rgb), 0.75);
}
#textAreaID {
    border: 1.5px solid rgba(var(--pm-hue1-rgb), 0.81);
}

.multiButton {
    background: linear-gradient(90deg,
        rgba(var(--pm-hue3-light-rgb), 0.75),
        rgba(var(--pm-hue1-rgb), 0.74));
    color: var(--pm-text);
    box-shadow:
        0 0 15px rgba(var(--pm-glow-warm), 0.5),
        0 0 30px rgba(var(--pm-glow-cool), 0.3);
}
.multiButton:hover {
    background: linear-gradient(145deg,
        rgba(var(--pm-hue1-bright-rgb), 0.81),
        var(--pm-hue2-bright));
    box-shadow:
        0 0 20px rgba(var(--pm-glow-warm), 0.7),
        0 0 40px rgba(var(--pm-glow-cool), 0.5);
}

/* ─── QUICK BUTTONS DROPDOWN ─── */

#quickbuttons-dropdown .qb-dropbtn {
    background: linear-gradient(145deg,
        rgba(var(--pm-hue1-bright-rgb), 0.81),
        var(--pm-hue2-bright));
    color: var(--pm-text);
    box-shadow:
        0 0 15px rgba(var(--pm-glow-warm), 0.7),
        0 0 30px rgba(var(--pm-glow-cool), 0.5);
}
#quickbuttons-dropdown .qb-dropdown-content {
    background-color: rgba(var(--pm-light-rgb), 0.81);
}
#quickbuttons-dropdown .qb-dropdown-content a {
    color: var(--pm-text-dark);
}
#quickbuttons-dropdown .qb-dropdown-content a:hover {
    background-color: rgba(var(--pm-neutral-rgb), 0.63);
}
#quickbuttons-dropdown:hover .qb-dropbtn {
    box-shadow:
        0 0 20px rgba(var(--pm-glow-warm), 0.9),
        0 0 40px rgba(var(--pm-glow-cool), 0.7);
}

